const [state, dispatch] = useReducer(formReducer, initialState);
useEffect(() => { if (state.step === 2) validate(state.fields); }, [state.step]);
function formReducer(state: FormState, action: FormAction): FormState {
  switch (action.type) { case 'field': return { ...state, fields: { ...state.fields, [action.name]: action.value } }; }
}
// TypeScript: FormAction is a discriminated union so every case is checked
